CREATE TRIGGER approvals_chat_delete AFTER DELETE ON runtime_agents BEGIN
               UPDATE approvals SET state='unknown',command=NULL,since=((julianday('now')-2440587.5)*86400.0)
                 WHERE agent=OLD.id AND state='answering';
               UPDATE approvals SET state='closed',reason='chat_deleted',at=((julianday('now')-2440587.5)*86400.0),fire_at=NULL
                 WHERE agent=OLD.id AND state='pending';
             END

CREATE TRIGGER chats_owner_delete AFTER DELETE ON runtime_agents BEGIN
           UPDATE turns SET state='interrupted',session=NULL,attempt=NULL,interrupt_ticket=NULL
             WHERE chat=OLD.id AND state IN ('starting','running');
           DELETE FROM sessions WHERE chat=OLD.id;
           DELETE FROM chats WHERE id=OLD.id;
         END

